int	binary_search(int *arr, int len, int target)
{
	int	lo = 0;
	int	hi = len - 1;

	while (lo <= hi)
	{
		int	mid = lo + (hi - lo) / 2;
		if (arr[mid] == target)
			return (mid);
		if (arr[mid] < target)
			lo = mid + 1;
		else
			hi = mid - 1;
	}
	return (-1);
}

void	selection_sort(int *arr, int len)
{
	for (int i = 0; i < len - 1; i++)
	{
		int	min = i;
		for (int j = i + 1; j < len; j++)
		{
			if (arr[j] < arr[min])
				min = j;
		}
		if (min != i)
		{
			int	t = arr[i];
			arr[i] = arr[min];
			arr[min] = t;
		}
	}
}

t_list	*reverse_list(t_list *head)
{
	t_list	*prev = NULL;
	t_list	*curr = head;
	t_list	*next = NULL;

	while (curr)
	{
		next = curr->next;
		curr->next = prev;
		prev = curr;
		curr = next;
	}
	return (prev);
}

int	partition(int *arr, int lo, int hi)
{
	int	pivot = arr[hi];
	int	i = lo - 1;

	for (int j = lo; j < hi; j++)
	{
		if (arr[j] < pivot)
		{
			i++;
			int	t = arr[i];
			arr[i] = arr[j];
			arr[j] = t;
		}
	}
	int	t = arr[i + 1];
	arr[i + 1] = arr[hi];
	arr[hi] = t;
	return (i + 1);
}

void	merge(int *arr, int l, int m, int r)
{
	int	n1 = m - l + 1;
	int	n2 = r - m;
	int	L[n1];
	int	R[n2];

	for (int i = 0; i < n1; i++)
		L[i] = arr[l + i];
	for (int j = 0; j < n2; j++)
		R[j] = arr[m + 1 + j];
	int	i = 0, j = 0, k = l;
	while (i < n1 && j < n2)
		arr[k++] = (L[i] <= R[j]) ? L[i++] : R[j++];
	while (i < n1)
		arr[k++] = L[i++];
	while (j < n2)
		arr[k++] = R[j++];
}

int	max_subarray(int *arr, int len)
{
	int	max_so_far = arr[0];
	int	max_ending_here = arr[0];

	for (int i = 1; i < len; i++)
	{
		max_ending_here = (arr[i] > max_ending_here + arr[i]) ? arr[i] : max_ending_here + arr[i];
		if (max_so_far < max_ending_here)
			max_so_far = max_ending_here;
	}
	return (max_so_far);
}

int	climbing_stairs(int n)
{
	if (n <= 2)
		return (n);
	int	first = 1;
	int	second = 2;
	for (int i = 3; i <= n; i++)
	{
		int	third = first + second;
		first = second;
		second = third;
	}
	return (second);
}

unsigned int	ft_strlcat(char *dest, char *src, unsigned int size)
{
	unsigned int	i = 0;
	unsigned int	j = 0;
	unsigned int	dlen = 0;

	while (dest[dlen] && dlen < size)
		dlen++;
	while (src[j])
		j++;
	if (size <= dlen)
		return (size + j);
	while (src[i] && (dlen + i) < (size - 1))
	{
		dest[dlen + i] = src[i];
		i++;
	}
	dest[dlen + i] = '\0';
	return (dlen + j);
}

int	ft_atoi(char *str)
{
	int	res = 0;
	int	sign = 1;

	while (*str == ' ' || (*str >= 9 && *str <= 13))
		str++;
	if (*str == '-' || *str == '+')
	{
		if (*str++ == '-')
			sign = -1;
	}
	while (*str >= '0' && *str <= '9')
		res = res * 10 + (*str++ - '0');
	return (res * sign);
}

char	*ft_strnstr(char *haystack, char *needle, size_t len)
{
	size_t	nlen = strlen(needle);
	if (!nlen)
		return (haystack);
	for (size_t i = 0; i + nlen <= len && haystack[i]; i++)
	{
		if (strncmp(&haystack[i], needle, nlen) == 0)
			return (&haystack[i]);
	}
	return (NULL);
}
